/* HEXA BATTLEGROUNDS upgrade — PART 3 OF 6. Only for databases that already ran setup part-01…; run in order. Safe to re-run. */ create or replace function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare a arenas; r record; v_changed boolean := false; v_sched text[]; v_next int; v_at timestamptz; v_target int; begin if not pg_try_advisory_xact_lock(hashtext('tick' || p_arena::text)) then return false; end if; select * into a from arenas where id = p_arena; if a.id is null or a.paused then return false; end if; if not p_force and a.last_tick_at is not null and a.last_tick_at > now() - interval '800 milliseconds' then return false; end if; update arenas set last_tick_at = now() where id = p_arena; if a.phase = 'shuttle' and now() >= a.shuttle_arrive_at then update arenas set phase = 'roles', roles_deadline = now() + _secs(_cfg(a.event_id, 'roles_seconds')) where id = p_arena; update teams set location_id = 'gate_1', state = 'idle' where arena_id = p_arena and ready; perform _feed(p_arena, 'shuttle.arrived', '{}'::jsonb); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'roles' and now() >= a.roles_deadline then perform _finalize_roles(p_arena); update arenas set phase = 'play', play_started_at = now() where id = p_arena; perform _feed(p_arena, 'role.assignment.completed', '{}'::jsonb); perform _feed(p_arena, 'map.revealed', '{}'::jsonb); perform _set_match_phase(p_arena, 0); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase not in ('play', 'finale') then if v_changed then perform _ping_arena(p_arena, 'phase'); end if; return v_changed; end if; for r in select id from teams where arena_id = p_arena and state = 'traveling' and travel_arrive_at <= now() loop perform _arrive(r.id); v_changed := true; end loop; for r in select id from battles where arena_id = p_arena and status = 'active' and deadline <= now() loop perform _resolve_battle(r.id, null); v_changed := true; end loop; for r in select id, kind, sync_round_id from mission_instances where arena_id = p_arena and status = 'active' and deadline <= now() and kind <> 'battle' loop perform _fail(r.id, 'expired'); v_changed := true; end loop; for r in select id from teams where arena_id = p_arena and state = 'recovery' and recovery_deadline <= now() loop perform _respawn(r.id, 'timeout'); v_changed := true; end loop; for r in select id from sync_rounds where arena_id = p_arena and status = 'active' and deadline <= now() loop update sync_rounds set status = 'closed' where id = r.id; update arenas set sync_round_id = null where id = p_arena and sync_round_id = r.id; perform _feed(p_arena, 'sync.closed', '{}'::jsonb); v_changed := true; end loop; select * into a from arenas where id = p_arena; if a.phase = 'play' and a.match_phase < 4 and a.phase_next_at is not null and now() >= a.phase_next_at then perform _set_match_phase(p_arena, a.match_phase + 1); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and not a.zone_hold and a.zone_next_at is null and a.zone_stage < 5 then v_target := _phase_zone_target(a.match_phase); if a.zone_stage < v_target then update arenas set zone_next_at = now() + _secs(_cfg(a.event_id, 'zone_warning')) where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and _cfg(a.event_id, 'zone_auto') = 1 and a.zone_next_at is null and a.zone_stage < 5 and not a.zone_hold then v_sched := string_to_array(_cfg_text(a.event_id, 'zone_schedule'), ','); v_next := trim(v_sched[a.zone_stage + 1])::int; if v_next is not null then v_at := a.play_started_at + make_interval(mins => v_next); if now() >= v_at - _secs(_cfg(a.event_id, 'zone_warning')) then update arenas set zone_next_at = greatest(v_at, now() + interval '10 seconds') where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; end if; select * into a from arenas where id = p_arena; if a.zone_next_at is not null and now() >= a.zone_next_at then perform _zone_advance(p_arena); v_changed := true; end if; if a.phase = 'play' and _cfg(a.event_id, 'airdrop_interval') > 0 and coalesce(a.last_airdrop_at, a.play_started_at) < now() - make_interval(mins => _cfg(a.event_id, 'airdrop_interval')) then perform _spawn_airdrop(p_arena, null, (array['common', 'common', 'rare', 'mystery', 'intel', 'cursed', 'legendary'])[1 + floor(random() * 7)::int]); v_changed := true; end if; update airdrops set status = 'expired' where arena_id = p_arena and status = 'open' and expires_at <= now(); if found then v_changed := true; end if; update mission_instances mi set status = 'cancelled' from airdrops ad where mi.airdrop_id = ad.id and ad.status = 'expired' and mi.status = 'active'; update alliances set status = 'expired' where arena_id = p_arena and status = 'proposed' and created_at < now() - interval '2 minutes'; update alliances set status = 'ended' where arena_id = p_arena and status = 'active' and expires_at <= now(); if v_changed then perform _ping_arena(p_arena, 'tick'); end if; return v_changed; end $$; create or replace function host_generate_teams(p_token text, p_count int) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_start int; v_out jsonb := '[]'::jsonb; i int; v_pin text; v_salt text; v_arena uuid; v_size int; v_team teams; begin v_ev := _auth_host(p_token); if p_count < 1 or p_count > 120 then raise exception 'BAD_COUNT'; end if; v_size := _cfg(v_ev, 'arena_size'); select coalesce(max(number), 0) into v_start from teams where event_id = v_ev; for i in 1..p_count loop v_pin := _new_pin(_cfg(v_ev, 'pin_length')); v_salt := _new_token(); select a.id into v_arena from arenas a where a.event_id = v_ev and a.phase = 'lobby' and (select count(*) from teams t where t.arena_id = a.id) < v_size order by a.number limit 1; if v_arena is null then raise exception 'ALL_MAPS_FULL'; end if; insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash) values (v_ev, v_arena, v_start + i, null, v_salt, _hash(v_salt || v_pin)) returning * into v_team; perform _add_item(v_team.id, 'pistol', 1); perform _add_item(v_team.id, 'medkit', 1); v_out := v_out || jsonb_build_object('number', v_team.number, 'name', v_team.name, 'pin', v_pin, 'bus', v_team.bus, 'map', (select number from arenas where id = v_arena)); end loop; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'generate_teams', jsonb_build_object('count', p_count)); return v_out; end $$;
